content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --success-color: #22c55e;
  --error-color: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.app-container {
  width: 100%;
  max-width: 600px;
  background-color: var(--card-bg);
  border-radius: 1rem;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  padding: 2rem;
  margin: auto;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.header p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.quiz-card {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.question-text {
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: #f1f5f9;
  padding: 1rem;
  border-radius: 0.5rem;
  border-left: 4px solid var(--primary-color);
}

.option-item {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.btn {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  width: 100%;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-option {
  background-color: #ffffff;
  color: var(--text-main);
  border: 1px solid var(--border-color);
  justify-content: flex-start;
  text-align: left;
  padding: 1rem;
  font-weight: 500;
}

.btn-option:hover {
  background-color: #f8fafc;
  border-color: var(--primary-color);
}

.result-card {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.score-display {
  text-align: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
  padding: 1.5rem;
  background-color: #eff6ff;
  border-radius: 0.75rem;
}

.explanation {
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 1rem;
  margin-top: 1rem;
  font-size: 0.95rem;
  color: var(--text-muted);
}

.explanation strong {
  color: var(--text-main);
}

export interface Question {
  id: number;
  questionText: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
}

export interface QuizState {
  currentQuestionIndex: number;
  score: number;
  selectedAnswers: number[];
  isFinished: boolean;
}

import { useState } from 'react';
import { Question, QuizState } from './types';
import Quiz from './Quiz';
import Result from './Result';

const questions: Question[] = [
  {
    id: 1,
    questionText: '日本で一番面積が大きい都道府県はどこでしょう？',
    options: ['岩手県', '北海道', '長野県', '新潟県'],
    correctAnswer: 1,
    explanation: '北海道は日本最大の都道府県で、全国の約22%の面積を占めています。'
  },
  {
    id: 2,
    questionText: '日本で一番高い山「富士山」の標高はどれでしょう？',
    options: ['3,776m', '3,190m', '3,026m', '3,931m'],
    correctAnswer: 0,
    explanation: '富士山の標高は3,776mで、日本最高峰の山です（静岡県と山梨県にまたがっています）。'
  },
  {
    id: 3,
    questionText: '琵琶湖がある都道府県はどこでしょう？',
    options: ['三重県', '岐阜県', '滋賀県', '京都府'],
    correctAnswer: 2,
    explanation: '琵琶湖は滋賀県にある日本最大の湖です。'
  },
  {
    id: 4,
    questionText: '日本最南端の島（有人島）である「波照間島」がある都道府県はどこでしょう？',
    options: ['鹿児島県', '東京都', '沖縄県', '高知県'],
    correctAnswer: 2,
    explanation: '波照間島は沖縄県八重山郡竹富町に属し、日本最南端の有人島です。'
  },
  {
    id: 5,
    questionText: '四国地方に含まれない県はどれでしょう？',
    options: ['香川県', '徳島県', '山口県', '高知県'],
    correctAnswer: 2,
    explanation: '山口県は本州（中国地方）に位置しています。四国は香川、徳島、愛媛、高知の4県です。'
  }
];

export default function App() {
  const [quizState, setQuizState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    selectedAnswers: [],
    isFinished: false,
  });

  const handleAnswer = (selectedOptionIndex: number) => {
    const currentQ = questions[quizState.currentQuestionIndex];
    const isCorrect = selectedOptionIndex === currentQ.correctAnswer;
    const newScore = isCorrect ? quizState.score + 1 : quizState.score;
    const newSelectedAnswers = [...quizState.selectedAnswers, selectedOptionIndex];
    const nextIndex = quizState.currentQuestionIndex + 1;

    if (nextIndex < questions.length) {
      setQuizState({
        currentQuestionIndex: nextIndex,
        score: newScore,
        selectedAnswers: newSelectedAnswers,
        isFinished: false,
      });
    } else {
      setQuizState({
        currentQuestionIndex: quizState.currentQuestionIndex,
        score: newScore,
        selectedAnswers: newSelectedAnswers,
        isFinished: true,
      });
    }
  };

  const handleRestart = () => {
    setQuizState({
      currentQuestionIndex: 0,
      score: 0,
      selectedAnswers: [],
      isFinished: false,
    });
  };

  return (
    <div className="app-container">
      <div className="header">
        <h1>日本の地理クイズ</h1>
        <p>日本の地理に関する全5問の4択クイズです。</p>
      </div>
      {!quizState.isFinished ? (
        <Quiz
          question={questions[quizState.currentQuestionIndex]}
          questionNumber={quizState.currentQuestionIndex + 1}
          totalQuestions={questions.length}
          onAnswer={handleAnswer}
        />
      ) : (
        <Result
          questions={questions}
          selectedAnswers={quizState.selectedAnswers}
          score={quizState.score}
          onRestart={handleRestart}
        />
      )}
    </div>
  );
}

import { Question } from './types';

interface QuizProps {
  question: Question;
  questionNumber: number;
  totalQuestions: number;
  onAnswer: (optionIndex: number) => void;
}

export default function Quiz({
  question,
  questionNumber,
  totalQuestions,
  onAnswer,
}: QuizProps) {
  return (
    <div className="quiz-card">
      <div style={{ fontSize: '0.9rem', color: 'var(--text-muted)' }}>
        第 {questionNumber} 問 / 全 {totalQuestions} 問
      </div>
      <div className="question-text">{question.questionText}</div>
      <div className="option-item">
        {question.options.map((option, index) => (
          <button
            key={index}
            className="btn btn-option"
            onClick={() => onAnswer(index)}
          >
            {index + 1}. {option}
          </button>
        ))}
      </div>
    </div>
  );
}

import { Question } from './types';

interface ResultProps {
  questions: Question[];
  selectedAnswers: number[];
  score: number;
  onRestart: () => void;
}

export default function Result({
  questions = [],
  selectedAnswers = [],
  score = 0,
  onRestart,
}: ResultProps) {
  return (
    <div className="result-card">
      <div className="score-display">
        クイズ終了！<br />
        正解数: {score} / {questions.length} 問
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
        <h3 style={{ fontSize: '1.1rem', fontWeight: 600 }}>解答と解説</h3>
        {questions.map((q, index) => {
          const selected = selectedAnswers[index];
          const isCorrect = selected === q.correctAnswer;
          return (
            <div key={q.id} style={{ borderBottom: '1px solid var(--border-color)', paddingBottom: '1rem' }}>
              <div style={{ fontWeight: 600, marginBottom: '0.5rem' }}>
                Q{index + 1}. {q.questionText}
              </div>
              <div style={{ fontSize: '0.9rem', marginBottom: '0.5rem' }}>
                あなたの回答: <span style={{ color: isCorrect ? 'var(--success-color)' : 'var(--error-color)', fontWeight: 600 }}>
                  {q.options[selected]} ({isCorrect ? '正解' : '不正解'})
                </span>
                {!isCorrect && (
                  <span style={{ marginLeft: '1rem' }}>
                    正解: <span style={{ color: 'var(--success-color)', fontWeight: 600 }}>{q.options[q.correctAnswer]}</span>
                  </span>
                )}
              </div>
              <div className="explanation">
                <strong>解説:</strong> {q.explanation}
              </div>
            </div>
          );
        })}
      </div>

      <button className="btn btn-primary" onClick={onRestart} style={{ marginTop: '1rem' }}>
        もう一度やり直す
      </button>
    </div>
  );
}
